    // -- idle hot probe: must hit with no PTW refill ----------------------
    void hot_probe_no_ptw(uint32_t did, uint64_t iova, uint64_t expect_spaddr,
                          uint8_t bank) {
        set_req(did, iova, 0x2, bank, true);
        if (!wait_accept()) FAIL_AT("hot_probe: request was not accepted");
        set_req(did, 0, 0, 0, false);
        bool saw_ptw = false;
        Resp r = pop_resp_track_ptw(saw_ptw);
        CHECK_AT(!r.error, "hot_probe: unexpected error response");
        CHECK_AT(r.bank == bank, "hot_probe: response bank mismatch");
        CHECK_AT(r.spaddr == expect_spaddr,
                 "hot_probe: unexpected translated address");
        CHECK_AT(!saw_ptw, "hot_probe: a hot entry triggered a PTW refill");
    }

    // Count observed IOTLB fills owned by a DID (non-vacuous fill checks).
    int count_fills(uint32_t did) {
        int n = 0;
        for (size_t i = 0; i < fills.size(); ++i)
            if (fills[i].did == did) ++n;
        return n;
    }

    // Spin until the policy is quiet and every response has been consumed.
    void drain_quiet(int maxc = 4000) {
        for (int i = 0; i < maxc; ++i) {
            tick();
            if (quiet_s && resp_q.empty()) return;
        }
        FAIL_AT("drain_quiet: quiet was never reached");
    }

    // Hold a bank-different cold A page, prove the warmed V probe fires the
    // fast path before A is released, then consume both responses and go quiet.
    void fast_prove_under_cold_a(uint64_t a_iova, uint64_t a_spaddr,
                                 uint64_t v_iova, uint64_t v_spaddr) {
        start_cold_a_and_hold(a_iova, 1);
        CHECK_AT(!quiet_s, "fast_prove: quiet while a cold A walk is held");

        latched_req_fire = false;  // no request is in flight at this point
        set_req(10, v_iova, 0x2, 0, true);
        if (!wait_accept()) FAIL_AT("fast_prove: V probe was not accepted");
        CHECK_AT(req_fire_fast,
                 "fast_prove: V probe was not taken by the fast path");
        set_req(10, 0, 0, 0, false);

        Resp rv = pop_resp();
        CHECK_AT(rv.bank == 0 && !rv.error && rv.spaddr == v_spaddr,
                 "fast_prove: V fast response mismatch");

        Resp ra = release_a();
        CHECK_AT(ra.bank == 1 && !ra.error && ra.spaddr == a_spaddr,
                 "fast_prove: A response mismatch after the fast hit");
        drain_quiet();
    }

    // Hold a bank-different cold A page, confirm V is neither accepted nor
    // fast while A is busy, then release A and let V walk the normal path.
    void block_then_normal_under_cold_a(uint64_t a_iova, uint64_t a_spaddr,
                                        int hold_cycles,
                                        uint64_t v_iova, uint64_t v_spaddr) {
        start_cold_a_and_hold(a_iova, 1);
        CHECK_AT(!quiet_s, "blocked: quiet while a cold A walk is held");

        latched_req_fire = false;  // no request is in flight at this point
        set_req(10, v_iova, 0x2, 0, true);
        bool any = false, fast = false;
        for (int i = 0; i < hold_cycles; ++i) {
            tick();
            if (req_fire) { any = true; if (req_fire_fast) fast = true; }
        }
        CHECK_AT(!any, "blocked: V accepted while a cold A was in flight");
        CHECK_AT(!fast, "blocked: fast path fired while a cold A was in flight");

        Resp ra = release_a();
        CHECK_AT(ra.bank == 1 && !ra.error && ra.spaddr == a_spaddr,
                 "blocked: A response mismatch");

        if (!wait_accept()) FAIL_AT("blocked: V never accepted after A drained");
        set_req(10, 0, 0, 0, false);
        bool saw_ptw = false;
        Resp rv = pop_resp_track_ptw(saw_ptw);
        CHECK_AT(rv.bank == 0 && !rv.error && rv.spaddr == v_spaddr,
                 "blocked: V response mismatch after the normal-path walk");
        drain_quiet();
    }

