      "new": "    void case_mode_gating(const char* name, bool n, bool p) {
        (void)name;
        reset(n, p, 10);

        // Warm V page 0 via the normal path.
        warm_leaf(10, 0x10000000ULL, 0x80000000ULL, 0);

        // The fast window only opens while a bank-different cold A walk is in
        // flight (n_window: state_q == PT && e3_ptw_active && bank differs),
        // so hold cold A page 0 before probing the warmed V entry.
        //   N / PN: V must fast-fire before A is released.
        //   S / P : V must be neither accepted nor fast until A has drained.
        if (n) {
            fast_prove_under_cold_a(0x20000000ULL, 0x90000000ULL,
                                    0x10000000ULL, 0x80000000ULL);
            CHECK_AT(saw_nonblock_fire,
                     "mode: nonblock_fire_o never asserted with N enabled");
        } else {
            block_then_normal_under_cold_a(0x20000000ULL, 0x90000000ULL, 60,
                                           0x10000000ULL, 0x80000000ULL);
            CHECK_AT(!saw_nonblock_fire,
                     "mode: nonblock_fire_o asserted with N disabled");
        }

        if (p) {
            check_all_fills(true);
        }
    }"
